const clean = (value) => String(value || "").replace(/\s+/g, " ").trim();

const guide = ({ topic, goal, facts, steps, examples, check, caution, wrong, terms = [], parentTip, sources }) => ({
  topic: clean(topic),
  goal: clean(goal),
  facts: facts.map(clean),
  steps: steps.map(clean),
  examples: examples.map(clean),
  check: clean(check),
  caution: clean(caution),
  wrong: wrong.map(clean),
  terms,
  parentTip: clean(parentTip || "Laat uw kind hardop uitleggen wat het doet. Geef pas hulp bij de stap waar het vastloopt."),
  sources,
});

const defaultSources = (subject) => {
  if (subject === "math") return ["vlaanderen.minimumdoelen.2026", "slo.rekenen.groep3-4", "leerpunt.explicit-feedback"];
  if (subject === "nl") return ["vlaanderen.minimumdoelen.2026", "slo.nederlands.groep3-4", "leerpunt.begrijpend-lezen"];
  if (["science_tech", "geo", "history"].includes(subject)) return ["vlaanderen.minimumdoelen.2026", "slo.orientatie.groep3-4"];
  if (subject === "ict") return ["vlaanderen.minimumdoelen.2026", "slo.digitale-geletterdheid"];
  if (subject === "arts") return ["vlaanderen.minimumdoelen.2026", "slo.kunstzinnige-orientatie"];
  if (subject === "pe") return ["vlaanderen.minimumdoelen.2026", "slo.bewegingsonderwijs"];
  return ["vlaanderen.minimumdoelen.2026", "leerpunt.explicit-feedback"];
};

function parentExplanation(profile) {
  return [
    `Wat leert uw kind?\n${profile.goal}`,
    `Zo legt u het uit\n${profile.facts.slice(0, 2).join(" ")}`,
    `Voorbeeld\n${profile.examples[0]}`,
    `Veelgemaakte fout\n${profile.caution}`,
    `Oefentip voor thuis\n${profile.parentTip}`,
  ].join("\n\n");
}

function distinct(values) {
  return [...new Set(values.map(clean).filter(Boolean))];
}

export function buildQuestionPool(profile, grade) {
  const topic = profile.topic ? ` over ${profile.topic.toLocaleLowerCase("nl-BE")}` : "";
  const shortPrompts = grade === 1
    ? [`Welke zin${topic} klopt?`, `Wat is waar${topic}?`, `Kies de juiste zin${topic}.`]
    : [`Welke zin${topic} klopt?`, `Wat is juist${topic}?`, `Kies de juiste uitleg${topic}.`];
  const questions = [];
  const add = (prompt, answer, distractors, explanation = answer) => {
    const options = distinct([answer, ...distractors]).slice(0, 4);
    const fillers = profile.wrong.filter((item) => !options.includes(item));
    while (options.length < 4 && fillers.length) options.push(fillers.shift());
    while (options.length < 4) options.push(`Deze keuze klopt niet (${options.length + 1}).`);
    questions.push({ prompt: clean(prompt), answer: clean(answer), options, explanation: clean(explanation) });
  };
  profile.facts.forEach((fact, index) => add(
    shortPrompts[index % shortPrompts.length],
    fact,
    [...profile.wrong.slice(index % Math.max(1, profile.wrong.length)), ...profile.wrong],
    fact,
  ));
  add(`Wat doe je bij ${profile.topic.toLocaleLowerCase("nl-BE")} eerst?`, profile.steps[0], [...profile.steps.slice(1), ...profile.wrong], `Begin met: ${profile.steps[0]}`);
  if (profile.steps[1]) add(`Wat doe je daarna bij ${profile.topic.toLocaleLowerCase("nl-BE")}?`, profile.steps[1], [profile.steps[0], ...profile.steps.slice(2), ...profile.wrong], `Daarna: ${profile.steps[1]}`);
  profile.examples.forEach((example, index) => add(
    index % 2 === 0 ? `Welk voorbeeld over ${profile.topic.toLocaleLowerCase("nl-BE")} klopt?` : `Welke situatie past bij ${profile.topic.toLocaleLowerCase("nl-BE")}?`,
    example,
    [...profile.wrong, profile.caution],
    example,
  ));
  add(`Hoe controleer je je werk bij ${profile.topic.toLocaleLowerCase("nl-BE")}?`, profile.check, [...profile.wrong, profile.caution], profile.check);
  add(`Welke fout moet je bij ${profile.topic.toLocaleLowerCase("nl-BE")} vermijden?`, profile.caution, [...profile.steps, profile.check], `Let op: ${profile.caution}`);
  const reviewAnswers = distinct([
    ...profile.facts,
    ...profile.steps,
    ...profile.examples,
    profile.check,
    profile.caution,
  ]);
  const reviewPrompts = [
    `Sam vertelt${topic}. Welke zin kan Sam juist zeggen?`,
    `Lina oefent${topic}. Welke zin helpt haar?`,
    `Noor legt${topic} uit. Welke zin kiest ze?`,
    `Milan controleert zijn werk${topic}. Welke zin gebruikt hij?`,
    `Welke zin zou de juf${topic} op het bord kunnen schrijven?`,
    `Welke zin past bij een goed voorbeeld${topic}?`,
    `Welke zin helpt je om rustig na te denken${topic}?`,
    `Welke zin toont dat je het begrepen hebt${topic}?`,
    `Wat kun je juist vertellen${topic}?`,
    `Welke uitleg kun je aan een klasgenoot geven${topic}?`,
    `Welke zin gebruik je om je antwoord te controleren${topic}?`,
    `Welke zin past bij de les${topic}?`,
  ];
  const reviewMoments = ["", " Denk terug aan het voorbeeld.", " Kijk ook naar de controle-stap."];
  let reviewIndex = 0;
  while (questions.length < 36) {
    const answer = reviewAnswers[reviewIndex % reviewAnswers.length];
    const prompt = `${reviewPrompts[reviewIndex % reviewPrompts.length]}${reviewMoments[Math.floor(reviewIndex / reviewPrompts.length)] || ""}`;
    add(prompt, answer, [...profile.wrong, ...reviewAnswers.filter((value) => value !== answer).slice(0, 2)], answer);
    reviewIndex += 1;
  }
  return questions;
}

export function grade1Guide(lesson, knowledgeProfile) {
  if (!knowledgeProfile) throw new Error(`Geen kennisprofiel voor ${lesson.id}`);
  const title = clean(knowledgeProfile.title?.[0] || lesson.title?.visible?.["nl-BE"]);
  const facts = (knowledgeProfile.facts || []).map((triple) => clean(triple[0])).filter(Boolean);
  const warning = clean(knowledgeProfile.warning?.[0] || "Gok niet. Kijk opnieuw naar het voorbeeld.");
  const subject = lesson.unitId?.split(".")?.[2] || "general";
  const category = lesson.curriculumCategoryId;
  const steps = category === "number_sense" || category === "measurement_geometry"
    ? ["Kijk goed naar de getallen of het materiaal.", "Leg of teken wat er gebeurt.", "Reken stap voor stap.", "Controleer met een tweede manier."]
    : category === "language_skills" || category === "spelling_grammar"
      ? ["Luister of lees het hele woord, de zin of de tekst.", "Doe de taalstap van de les rustig.", "Lees of zeg het resultaat opnieuw.", "Verbeter één fout als dat nodig is."]
      : subject === "pe"
        ? ["Luister naar het startsignaal en kijk naar de veilige ruimte.", "Voer de beweging rustig uit.", "Stop bij pijn of onveiligheid.", "Probeer opnieuw met één kleine verbetering."]
        : ["Kijk of luister eerst goed.", "Benoem wat je echt ziet of hoort.", "Voer de opdracht stap voor stap uit.", "Vertel hoe je weet dat het klopt."];
  const examples = distinct(facts.slice(1, 6));
  while (examples.length < 2) examples.push(`Je toont ${title.toLowerCase()} met materiaal, een tekening of een korte uitleg.`);
  const terms = (knowledgeProfile.terms || []).map((triple) => ({
    term: clean(triple[0]),
    translated: { "fr-BE": clean(triple[1]), "en-US": clean(triple[2]) },
  }));
  const wrong = category === "number_sense" || category === "measurement_geometry"
    ? ["Ik hoef de getallen, vormen of meting niet te controleren.", "De volgorde van de rekenstappen maakt nooit uit.", "Gokken geeft altijd een juist antwoord."]
    : category === "language_skills" || category === "spelling_grammar"
      ? ["Ik hoef niet naar alle klanken, letters of woorden te kijken.", "De volgorde van letters en woorden maakt nooit uit.", "Gokken op de prent is altijd voldoende."]
      : subject === "pe"
        ? ["Ik begin zonder naar de veilige ruimte te kijken.", "Pijn is een signaal om gewoon door te gaan.", "Ik hoef niet naar het stopsignaal te luisteren."]
        : subject === "arts"
          ? ["Ik kies materiaal zonder te kijken wat het doet.", "Ik hoef niet te oefenen of naar mijn werk te kijken.", "Iedere keuze geeft altijd exact hetzelfde effect."]
          : ["Eén gok is even goed als goed kijken of luisteren.", "Veiligheid en duidelijke aanwijzingen zijn niet belangrijk.", "Ik hoef mijn voorbeeld of antwoord nooit te controleren."];
  return guide({
    topic: title,
    goal: `Je leert ${title.toLowerCase()} begrijpen en gebruiken.`,
    facts: distinct(facts.slice(0, 5)),
    steps,
    examples: examples.slice(0, 3),
    check: facts[6] || "Vertel je antwoord en wijs aan waardoor je het weet.",
    caution: warning,
    wrong,
    terms,
    parentTip: subject === "math"
      ? "Gebruik kleine voorwerpen, geld, een meetlat of een eenvoudige tekening. Laat uw kind eerst leggen en pas daarna rekenen."
      : subject === "nl"
        ? "Lees samen kort en vaak. Laat uw kind klanken, woorden of zinnen hardop zeggen en geef onmiddellijk rustige feedback."
        : "Koppel de uitleg aan iets thuis of buiten dat uw kind kan zien, doen of aanwijzen.",
    sources: defaultSources(subject),
  });
}

