export function grade2Guide(lesson, sourceUnit) {
  const set = lesson.stages.flatMap((stage) => stage.exerciseSets || [])[0];
  const mode = set?.parameters?.mode;
  const math = mathProfile(mode);
  const title = lesson.title.visible["nl-BE"];
  if (math) return { ...math, topic: title };
  const subject = sourceUnit?.subjectId || lesson.unitId?.split(".")?.[2] || "general";
  return { ...topicGuide(title, subject), topic: title };
}

